function decrementZekr(id) {
    const zekr = state.activeAzkar.find(z => z.id === id);
    if(zekr && zekr.count > 0) {
        zekr.count--;
        
        // Haptic vibe mock
        if(navigator.vibrate) {
            navigator.vibrate(30);
        }
        
        renderAzkar();
    }
}

